package io.knowledgebrain.learning;
import java.time.*;
import java.util.*;
import jakarta.servlet.http.Cookie;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class MediaEvidenceApiTest {
 MediaEvidenceStore store;MediaReferenceClient content;SpaceAuthorizationClient auth;MediaEvidenceController api;UUID space,roadmap,node,actor,note,item;
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();roadmap=ids.next();node=ids.next();actor=ids.next();note=ids.next();item=ids.next();store=mock(MediaEvidenceStore.class);content=mock(MediaReferenceClient.class);auth=mock(SpaceAuthorizationClient.class);when(auth.authorize(eq(space),any(),anyBoolean(),anyString())).thenReturn(actor);var m=new SimpleMeterRegistry();api=new MediaEvidenceController(store,new RoadmapController(mock(RoadmapStore.class),auth,m,"https://localhost:8443"),content,m);}
 MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/api/spaces/"+space+"/roadmaps/"+roadmap+"/media-evidence");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void freshAuthorityBeforeEveryReadAndDenialStopsCanonicalAccess(){when(store.page(space,roadmap,null,20)).thenReturn(new MediaEvidenceStore.Page(List.of(),null));assertEquals("no-store",api.page(space.toString(),roadmap.toString(),r("GET",null)).getHeaders().getCacheControl());api.page(space.toString(),roadmap.toString(),r("GET",null));verify(auth,times(2)).authorize(eq(space),eq("a".repeat(43)),eq(false),anyString());reset(store);when(auth.authorize(eq(space),any(),anyBoolean(),anyString())).thenThrow(new ResponseStatusException(HttpStatus.FORBIDDEN));assertThrows(ResponseStatusException.class,()->api.get(space.toString(),roadmap.toString(),item.toString(),r("GET",null)));verifyNoInteractions(store,content);}
 @Test void strictMemoOnlyStrongIndependentEtagAndSameOrigin()throws Exception{for(String etag:List.of("\"rm1\"","\"ss1\"","\"me0\"","W/\"me1\"","*","\"me01\"")){var req=r("PUT","{\"memo\":\"ok\"}");req.addHeader("If-Match",etag);assertThrows(ResponseStatusException.class,()->api.edit(space.toString(),roadmap.toString(),item.toString(),req));}assertEquals(428,assertThrows(ResponseStatusException.class,()->api.edit(space.toString(),roadmap.toString(),item.toString(),r("PUT","{}"))).getStatusCode().value());for(String body:List.of("{\"memo\":\"a\",\"memo\":\"b\"}","{\"memo\":\"a\",\"mediaId\":\"spoof\"}","{\"memo\":\"a\"} {}")){var req=r("PUT",body);req.addHeader("If-Match","\"me1\"");assertThrows(ResponseStatusException.class,()->api.edit(space.toString(),roadmap.toString(),item.toString(),req));}var cross=r("DELETE",null);cross.removeHeader("Origin");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.retire(space.toString(),roadmap.toString(),item.toString(),cross)).getStatusCode().value());verifyNoInteractions(store,content);}
 @Test void createRequiresRequestKeyAndExactServerOwnedFieldsAndQueriesAreStrict()throws Exception{String body="{\"nodeId\":\""+node+"\",\"mediaId\":\""+note+"\",\"mediaVersion\":1,\"memo\":\"ok\"}";assertThrows(ResponseStatusException.class,()->api.link(space.toString(),roadmap.toString(),r("POST",body)));for(String invalid:List.of(body.replace("1,","1.5,"),body.replace("1,","9223372036854775808,"),body.replace("\"memo\"","\"actorId\""),body.substring(0,body.length()-1)+",\"evidenceId\":\"spoof\"}")){var req=r("POST",invalid);req.addHeader("Idempotency-Key","b".repeat(32));assertThrows(ResponseStatusException.class,()->api.link(space.toString(),roadmap.toString(),req));}var query=r("GET",null);query.addParameter("limit","1","2");assertThrows(ResponseStatusException.class,()->api.page(space.toString(),roadmap.toString(),query));verifyNoInteractions(store,content);}
}
